-- CCNA 2.0 simlet and topology questions
-- Generated 29 questions

-- Ensure topology question type exists
ALTER TABLE questions DROP CONSTRAINT IF EXISTS questions_question_type_check;
ALTER TABLE questions ADD CONSTRAINT questions_question_type_check
  CHECK (question_type IN ('single-choice', 'multiple-choice', 'drag-drop', 'fill-blank', 'simlet', 'topology'));

INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('278e560a-1c24-52c1-a5f1-765950427c36', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'simlet', 3, 'analyze', $$Refer to the switch output:

SW1# show interfaces trunk
Port        Mode         Encapsulation  Status        Native vlan
Gi0/1       on           802.1q         trunking      99
Gi0/2       on           802.1q         trunking      99

SW1# show vlan brief
VLAN Name                             Status    Ports
---- -------------------------------- --------- -------------------------------
1    default                          active    Gi0/3, Gi0/4
10   SALES                            active
20   ENG                              active
99   MGMT                             active

Which ports carry traffic for VLAN 10?$$::text, $$[{"id": "A", "text": "Only Gi0/1 and Gi0/2", "is_correct": true}, {"id": "B", "text": "Only Gi0/3 and Gi0/4", "is_correct": false}, {"id": "C", "text": "Gi0/1, Gi0/2, Gi0/3, and Gi0/4", "is_correct": false}, {"id": "D", "text": "No ports carry VLAN 10", "is_correct": false}]$$::jsonb, $$Trunk ports carry all active VLANs across the link. Access ports in VLAN 1 do not carry VLAN 10.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$2.0 Network Access$$::text, 20.0, 'bf28d97d24295045', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b37e398d-199b-56e8-bed9-87b624a6a374', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'topology', 3, 'analyze', $$A topology shows two switches SW1 and SW2 connected by Gi0/1 on both ends.
SW1 is configured with:
 interface GigabitEthernet0/1
  switchport mode trunk
  switchport trunk allowed vlan 10,20
SW2 is configured with:
 interface GigabitEthernet0/1
  switchport mode dynamic desirable

What is the resulting state of the link?$$::text, $$[{"id": "A", "text": "It becomes a trunk carrying VLANs 10 and 20", "is_correct": true}, {"id": "B", "text": "It remains an access link", "is_correct": false}, {"id": "C", "text": "It becomes a trunk carrying all VLANs", "is_correct": false}, {"id": "D", "text": "The link is administratively down", "is_correct": false}]$$::jsonb, $$SW1 is statically configured as trunk; SW2 dynamic desirable will negotiate to trunk. The allowed VLAN list on SW1 restricts traffic to 10 and 20.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$2.0 Network Access$$::text, 20.0, 'e97cbacc1ba23160', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7d699f77-cedd-5104-8a14-59d025191719', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'topology', 4, 'troubleshoot', $$Topology: PC1 is in VLAN 10 on SW1 port Fa0/1. PC2 is in VLAN 10 on SW2 port Fa0/1. The switches are connected via Gi0/1 trunk. A router-on-a-stick router R1 is connected to SW1 Gi0/2 trunk.
PC1 cannot reach PC2, but both can reach their default gateway on R1. What is the most likely cause?$$::text, $$[{"id": "A", "text": "The native VLAN mismatch between SW1 and SW2", "is_correct": false}, {"id": "B", "text": "VLAN 10 is not allowed on the trunk between SW1 and SW2", "is_correct": true}, {"id": "C", "text": "R1 subinterface encapsulation is wrong", "is_correct": false}, {"id": "D", "text": "PC1 default gateway is missing", "is_correct": false}]$$::jsonb, $$If both PCs can reach the gateway but not each other, inter-switch trunk is likely missing VLAN 10.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$2.0 Network Access$$::text, 20.0, '51f3f23a5ea32207', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0dc223cc-2bab-5b8f-9637-afe3a0afb986', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'topology', 2, 'understand', $$Refer to the STP topology:

       [SW1]  (Bridge ID: 32768.0000.0000.0001)
      /     \
   [SW2]     [SW3]
   (32768.0000.0000.0002)  (32768.0000.0000.0003)

All links are GigabitEthernet with equal cost. Which switch is the root bridge?$$::text, $$[{"id": "A", "text": "SW1", "is_correct": true}, {"id": "B", "text": "SW2", "is_correct": false}, {"id": "C", "text": "SW3", "is_correct": false}, {"id": "D", "text": "Cannot determine", "is_correct": false}]$$::jsonb, $$Lowest bridge ID wins root bridge election. SW1 has the lowest MAC portion.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$2.0 Network Access$$::text, 20.0, '8204348a6758c157', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c89da141-b680-5cc8-8227-2c5e39fee8e2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'topology', 3, 'analyze', $$In the same topology, SW1 is root. Which ports on SW2 and SW3 are root ports?$$::text, $$[{"id": "A", "text": "Both upstream ports toward SW1", "is_correct": true}, {"id": "B", "text": "Both downstream ports toward each other", "is_correct": false}, {"id": "C", "text": "All ports are root ports", "is_correct": false}, {"id": "D", "text": "No root ports exist on non-root switches", "is_correct": false}]$$::jsonb, $$Each non-root switch selects one root port — the port with lowest cost to root, which faces upstream.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$2.0 Network Access$$::text, 20.0, 'e432a4bbbe6d6d0f', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4ed51397-3a8b-5cfe-92fb-ba13d3007c93', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'topology', 3, 'analyze', $$Topology: R1--(Area 0)--R2--(Area 1)--R3
R1 has networks 10.1.1.0/24 and 10.1.2.0/24 in Area 0. R3 has 10.3.3.0/24 in Area 1.
What LSA type does R1 receive for 10.3.3.0/24?$$::text, $$[{"id": "A", "text": "Type 1", "is_correct": false}, {"id": "B", "text": "Type 2", "is_correct": false}, {"id": "C", "text": "Type 3", "is_correct": true}, {"id": "D", "text": "Type 5", "is_correct": false}]$$::jsonb, $$Type 3 summary LSAs are generated by ABRs to advertise inter-area routes.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$3.0 IP Connectivity$$::text, 25.0, '7db471fef747fbe4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a3b815cc-a600-5fa5-841b-66d2487c418d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'simlet', 3, 'apply', $$Refer to the routing table:

O   10.0.0.0/8 [110/2] via 192.168.1.1
O   10.1.0.0/16 [110/3] via 192.168.1.2
O   10.1.1.0/24 [110/4] via 192.168.1.3

Which next-hop is used for traffic to 10.1.1.50?$$::text, $$[{"id": "A", "text": "192.168.1.1", "is_correct": false}, {"id": "B", "text": "192.168.1.2", "is_correct": false}, {"id": "C", "text": "192.168.1.3", "is_correct": true}, {"id": "D", "text": "Load-balanced across all three", "is_correct": false}]$$::jsonb, $$Longest prefix match selects /24 route for 10.1.1.50.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$3.0 IP Connectivity$$::text, 25.0, 'c0ec2349d02afe8b', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('023e1c39-ac1a-5d21-ad87-bb59341b147b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'topology', 4, 'analyze', $$EIGRP topology:

        [R1]
      /      \
   [R2]      [R3]
   FD=1000   FD=2000
   AD=800    AD=1500

From R1, what is the feasible successor to reach the destination behind R2/R3?$$::text, $$[{"id": "A", "text": "R2 because it has the lowest FD", "is_correct": false}, {"id": "B", "text": "R2 is the successor; R3 is not a feasible successor", "is_correct": false}, {"id": "C", "text": "R3 if its AD is less than the successor FD", "is_correct": true}, {"id": "D", "text": "Both R2 and R3 are feasible successors", "is_correct": false}]$$::jsonb, $$Successor is R2 (lowest FD). Feasible successor must have AD < successor FD. R3 AD=1500 < 1000 is false, so R3 is not feasible.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$3.0 IP Connectivity$$::text, 25.0, '9d4401c494a9afe9', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ffe4b635-20ea-5769-902e-74a6cd3aea58', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'simlet', 3, 'analyze', $$Router# show ip nat translations
Pro Inside global      Inside local       Outside local      Outside global
tcp 203.0.113.5:5001   192.168.1.10:5001  8.8.8.8:443        8.8.8.8:443
tcp 203.0.113.5:5002   192.168.1.11:5002  8.8.8.8:443        8.8.8.8:443

What type of NAT is shown?$$::text, $$[{"id": "A", "text": "Static NAT", "is_correct": false}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT / NAT overload", "is_correct": true}, {"id": "D", "text": "Dynamic PAT with pool", "is_correct": false}]$$::jsonb, $$Multiple inside local addresses share one inside global address with unique source ports — PAT overload.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$4.0 IP Services$$::text, 15.0, 'ce261f9514529ed7', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87ca9c3d-5a8a-52c3-84f6-6aa50a2b02dc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'simlet', 3, 'analyze', $$The following ACL is applied inbound on R1 Gi0/0 facing the internal network:

ip access-list extended BLOCK
 10 permit tcp 10.1.1.0 0.0.0.255 any eq 80
 20 deny ip 10.1.1.0 0.0.0.255 10.2.2.0 0.0.0.255
 30 permit ip any any

A host 10.1.1.50 sends TCP traffic to 10.2.2.10 port 80. What happens?$$::text, $$[{"id": "A", "text": "Permitted by line 10", "is_correct": true}, {"id": "B", "text": "Denied by line 20", "is_correct": false}, {"id": "C", "text": "Permitted by line 30", "is_correct": false}, {"id": "D", "text": "Dropped by implicit deny", "is_correct": false}]$$::jsonb, $$ACLs process in order. Line 10 permits TCP from 10.1.1.0/24 to any port 80 before line 20 denies.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$5.0 Security Fundamentals$$::text, 15.0, 'fbb70ea93b93651b', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c45eb08-a1b5-5cd9-8237-f673512a6ad6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'topology', 3, 'troubleshoot', $$Topology shows a DHCP server at 10.1.1.10 and a client PC on a different subnet separated by a router.
The client fails to obtain an IP address. Which router configuration is most likely missing?$$::text, $$[{"id": "A", "text": "ip helper-address 10.1.1.10 on the client-facing interface", "is_correct": true}, {"id": "B", "text": "ip address dhcp on the server-facing interface", "is_correct": false}, {"id": "C", "text": "A static route to 10.1.1.10", "is_correct": false}, {"id": "D", "text": "DHCP snooping on the switch", "is_correct": false}]$$::jsonb, $$Routers do not forward DHCP broadcasts between subnets without an ip helper-address to relay to the DHCP server.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$4.0 IP Services$$::text, 15.0, '0716f77acb101e1f', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e3a9bc93-0a9c-569e-b187-de8cff3583f4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'simlet', 2, 'understand', $$Two routers R1 and R2 run HSRP on VLAN 10. R1 has priority 110, R2 has priority 100.
Preempt is configured on both. R1 reboots and comes back online. Which router becomes Active?$$::text, $$[{"id": "A", "text": "R1", "is_correct": true}, {"id": "B", "text": "R2", "is_correct": false}, {"id": "C", "text": "Neither", "is_correct": false}, {"id": "D", "text": "Both become Active", "is_correct": false}]$$::jsonb, $$With preempt, the router with highest priority takes over as Active when it comes online.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$4.0 IP Services$$::text, 15.0, 'a516243cac8fb8e2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('509028d8-2fed-58cd-bb97-82ef0eb94ed4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'simlet', 3, 'analyze', $$Switch ports Gi0/1 and Gi0/2 are bundled into Port-channel 1 with mode active on both ends.
The neighbor switch uses mode passive. What is the resulting negotiation state?$$::text, $$[{"id": "A", "text": "LACP forms the bundle because active and passive negotiate", "is_correct": true}, {"id": "B", "text": "PAgP forms the bundle", "is_correct": false}, {"id": "C", "text": "No bundle forms; both sides must be active", "is_correct": false}, {"id": "D", "text": "The ports become a static trunk", "is_correct": false}]$$::jsonb, $$LACP active negotiates with LACP passive. PAgP is Cisco proprietary and requires PAgP modes.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$2.0 Network Access$$::text, 20.0, '9e3311befa658cd2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7c948ea2-286c-539f-9b6b-8cf144a43f36', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'topology', 2, 'apply', $$Topology: A small office uses a single AP on channel 6 in 2.4 GHz. Neighboring APs are detected on channels 4 and 8.
What is the recommended channel change?$$::text, $$[{"id": "A", "text": "Channel 1 or 11", "is_correct": true}, {"id": "B", "text": "Channel 5", "is_correct": false}, {"id": "C", "text": "Channel 6 with higher power", "is_correct": false}, {"id": "D", "text": "Channel 9", "is_correct": false}]$$::jsonb, $$Channels 1, 6, and 11 are the non-overlapping 2.4 GHz channels. Channel 4/8 overlap with 6.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$2.0 Network Access$$::text, 20.0, '6b3eb0465803f999', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09b6195b-70c7-588c-bbcc-bfb2f8a9039d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'simlet', 3, 'troubleshoot', $$Switch port security output:

Port  Security  Violation  Action   Status
Fa0/1 Enabled   Restrict   Restrict Secure-shutdown

What caused the interface to enter err-disabled?$$::text, $$[{"id": "A", "text": "A MAC address violation with shutdown violation mode", "is_correct": true}, {"id": "B", "text": "A MAC address violation with restrict mode", "is_correct": false}, {"id": "C", "text": "DTP negotiation failure", "is_correct": false}, {"id": "D", "text": "A BPDU received on a PortFast port", "is_correct": false}]$$::jsonb, $$Secure-shutdown/err-disabled occurs when port security violation mode is shutdown. Restrict mode increments counters but does not shut down.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$5.0 Security Fundamentals$$::text, 15.0, 'aa95a0694f861db2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5321a05b-14e0-5317-ad92-713d96599d2a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'topology', 3, 'apply', $$Topology shows a /64 IPv6 subnet 2001:db8:1:1::/64. Host A auto-configures with EUI-64 using MAC 00:1A:2B:3C:4D:5E.
What is the host identifier portion?$$::text, $$[{"id": "A", "text": "021A:2BFF:FE3C:4D5E", "is_correct": true}, {"id": "B", "text": "001A:2B3C:4D5E", "is_correct": false}, {"id": "C", "text": "021A:2B3C:4D5E", "is_correct": false}, {"id": "D", "text": "FE80::021A:2BFF:FE3C:4D5E", "is_correct": false}]$$::jsonb, $$EUI-64 inserts FF:FE in the middle and flips the U/L bit (02 instead of 00).$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$1.0 Network Fundamentals$$::text, 15.0, 'dfef57d68e326728', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('45f1a970-c374-5604-b654-12a98892ceda', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'simlet', 2, 'apply', $$A router interface is configured with ip address 192.168.5.65 255.255.255.224.
What is the broadcast address of this subnet?$$::text, $$[{"id": "A", "text": "192.168.5.95", "is_correct": true}, {"id": "B", "text": "192.168.5.64", "is_correct": false}, {"id": "C", "text": "192.168.5.96", "is_correct": false}, {"id": "D", "text": "192.168.5.127", "is_correct": false}]$$::jsonb, $$/27 block size is 32. Network 192.168.5.64, broadcast 192.168.5.95, hosts .65-.94.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$1.0 Network Fundamentals$$::text, 15.0, '38d39770c2d7c08b', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0345542b-eb51-5f0c-b03d-618098c0be7a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'simlet', 2, 'understand', $$A Python script uses requests to POST to https://router/restconf/data/Cisco-IOS-XE-native:native/interface.
What type of API is being used?$$::text, $$[{"id": "A", "text": "NETCONF over SSH", "is_correct": false}, {"id": "B", "text": "RESTCONF", "is_correct": true}, {"id": "C", "text": "SOAP", "is_correct": false}, {"id": "D", "text": "gRPC", "is_correct": false}]$$::jsonb, $$RESTCONF uses HTTP/REST methods and URIs based on YANG models.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$6.0 Automation and Programmability$$::text, 10.0, '9ded4f561ea52dc2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0592e372-eee1-5267-a468-ff04b7aca350', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'simlet', 2, 'understand', $$An Ansible playbook targets switches with the ios_config module and a Jinja2 template.
Which component supplies the per-device variables?$$::text, $$[{"id": "A", "text": "Inventory", "is_correct": true}, {"id": "B", "text": "Galaxy", "is_correct": false}, {"id": "C", "text": "Module index", "is_correct": false}, {"id": "D", "text": "Vault", "is_correct": false}]$$::jsonb, $$Inventory files define hosts and host/group variables used by playbooks and templates.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$6.0 Automation and Programmability$$::text, 10.0, 'e87444ecf46c34f6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f25748b8-8515-5eaa-83b0-60c850d7ac47', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'topology', 3, 'analyze', $$Topology: Three routers R1, R2, and R3 are connected in a full mesh using serial links.
R1 has a single T1 link to R2 and a T3 link to R3. Which path will OSPF prefer to reach R3?$$::text, $$[{"id": "A", "text": "T1 path through R2 because it has lower bandwidth", "is_correct": false}, {"id": "B", "text": "Direct T3 path to R3 because it has lower cost", "is_correct": true}, {"id": "C", "text": "OSPF load-balances across both paths", "is_correct": false}, {"id": "D", "text": "The path with fewer hops", "is_correct": false}]$$::jsonb, $$OSPF cost is based on bandwidth. T3 has higher bandwidth and lower cost than T1.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$3.0 IP Connectivity$$::text, 25.0, '9b29f15846db2eb6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8d3d1644-78e7-5b88-a773-a1aa6199f880', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'topology', 4, 'troubleshoot', $$Refer to the topology:

   [SW1]---[SW2]---[SW3]
   VLAN 10 VLAN 10 VLAN 10

All inter-switch links are trunks allowing VLAN 10. A host in VLAN 10 on SW1 cannot reach a host in VLAN 10 on SW3.
What is the most likely cause?$$::text, $$[{"id": "A", "text": "VLAN 10 is not allowed on the SW2-SW3 trunk", "is_correct": true}, {"id": "B", "text": "Native VLAN mismatch on SW1-SW2 trunk", "is_correct": false}, {"id": "C", "text": "STP blocked all VLAN 10 ports", "is_correct": false}, {"id": "D", "text": "The hosts are in different subnets", "is_correct": false}]$$::jsonb, $$If VLAN 10 is missing on one trunk segment, traffic cannot traverse the full Layer 2 path.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$2.0 Network Access$$::text, 20.0, '14104b7eb9d3c78d', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71f139a3-22e9-5f61-b37d-b9942234c836', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'topology', 3, 'analyze', $$Topology:

   [R1]---192.168.1.0/30---[R2]---192.168.2.0/30---[R3]

R1 has a static route to 10.0.0.0/8 pointing to R2. R2 has a static route to 10.0.0.0/8 pointing to R3.
Which routing problem is most likely if R2 loses its route to R3?$$::text, $$[{"id": "A", "text": "R1 will continue sending traffic to R2, creating a black hole", "is_correct": true}, {"id": "B", "text": "R1 will automatically reroute via a directly connected path", "is_correct": false}, {"id": "C", "text": "R2 will advertise the loss to R1 via OSPF", "is_correct": false}, {"id": "D", "text": "Static routes will converge in 30 seconds", "is_correct": false}]$$::jsonb, $$Static routes do not dynamically adapt. R1 keeps forwarding to R2, which cannot reach the destination.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$3.0 IP Connectivity$$::text, 25.0, 'cfaef1ee50a60aa9', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f84293a3-010b-5e86-82c2-682540ba91b7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'topology', 3, 'analyze', $$Refer to the wireless topology:

   [AP1] <--channel 36--> [AP2] <--channel 44--> [AP3]

All APs are in the 5 GHz band using 20 MHz channels. Which statement is true?$$::text, $$[{"id": "A", "text": "Channels 36, 40, 44, and 48 are all non-overlapping 20 MHz channels", "is_correct": false}, {"id": "B", "text": "AP1, AP2, and AP3 are all on non-overlapping channels", "is_correct": true}, {"id": "C", "text": "Channel 36 overlaps with channel 44", "is_correct": false}, {"id": "D", "text": "5 GHz channels never overlap", "is_correct": false}]$$::jsonb, $$In 5 GHz, channels 36, 40, 44, 48 are non-overlapping when using 20 MHz widths.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$2.0 Network Access$$::text, 20.0, '33115c1a94c62845', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fad9208e-5799-5a04-a755-1803e89dd6bc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'topology', 3, 'understand', $$Topology: A router has two WAN links — a primary Ethernet circuit and a backup DSL circuit.
A floating static route is configured for the backup with a higher administrative distance.
Under what condition will the floating static route appear in the routing table?$$::text, $$[{"id": "A", "text": "When the primary route fails", "is_correct": true}, {"id": "B", "text": "When the primary route has a higher metric", "is_correct": false}, {"id": "C", "text": "When the backup link has lower bandwidth", "is_correct": false}, {"id": "D", "text": "Always, because it is a static route", "is_correct": false}]$$::jsonb, $$A floating static route is installed only when the primary route (lower AD) is no longer available.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$3.0 IP Connectivity$$::text, 25.0, 'e3f4d22c50c007a1', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a95624e4-38bf-5ac8-901a-fb3343fa08fe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'topology', 4, 'troubleshoot', $$Refer to the topology:

   [PC]---[R1]---[R2]---[Server]
   192.168.1.0/24  10.0.0.0/30  172.16.0.0/24

The PC can ping R1 but not the Server. R1 has a route to 172.16.0.0/24 via R2. What is the most likely issue?$$::text, $$[{"id": "A", "text": "R2 does not have a return route to 192.168.1.0/24", "is_correct": true}, {"id": "B", "text": "The Server is powered off", "is_correct": false}, {"id": "C", "text": "R1 default gateway is wrong", "is_correct": false}, {"id": "D", "text": "PC subnet mask is incorrect", "is_correct": false}]$$::jsonb, $$For end-to-end reachability, return traffic must have a route back to the source network.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$3.0 IP Connectivity$$::text, 25.0, '652e277c15781c3b', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf92d610-84e4-5bf3-912f-817ad3d8615f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'topology', 2, 'understand', $$Topology:

       [R1]
      /    \
   [SW1]  [SW2]
     |      |
   [PC1]  [PC2]

PC1 and PC2 are in the same VLAN and subnet. R1 provides a gateway for the VLAN.
Which device breaks the broadcast domain between PC1 and PC2?$$::text, $$[{"id": "A", "text": "SW1", "is_correct": false}, {"id": "B", "text": "SW2", "is_correct": false}, {"id": "C", "text": "R1", "is_correct": true}, {"id": "D", "text": "No device; they are in the same VLAN", "is_correct": false}]$$::jsonb, $$Routers break up broadcast domains. Switches in the same VLAN extend the broadcast domain.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$1.0 Network Fundamentals$$::text, 15.0, 'a36b04134421023e', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9479919-011d-5e1d-980a-bcdbd4c94332', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'topology', 1, 'understand', $$Refer to the network topology:

   [Internet]---[Firewall]---[Core]---[Access]---[Host]

Which device is best placed to perform stateful packet inspection between the Internet and internal network?$$::text, $$[{"id": "A", "text": "Core switch", "is_correct": false}, {"id": "B", "text": "Access switch", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": true}, {"id": "D", "text": "Host", "is_correct": false}]$$::jsonb, $$A stateful firewall is the correct device to enforce security policies at the network edge.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$5.0 Security Fundamentals$$::text, 15.0, 'a2a602ebe94ddb2e', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6104ef38-266a-5e0c-9cf9-7c3cbc9339b9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'topology', 2, 'understand', $$Topology:

   [R1]---[R2]---[R3]
   10.1.1.0/30  10.1.2.0/30

RIP is running on all routers. R1 advertises 192.168.1.0/24. How does R3 learn this route?$$::text, $$[{"id": "A", "text": "As a directly connected route", "is_correct": false}, {"id": "B", "text": "As a RIP route with hop count 2", "is_correct": true}, {"id": "C", "text": "As a static route", "is_correct": false}, {"id": "D", "text": "As an OSPF route", "is_correct": false}]$$::jsonb, $$RIP increments hop count at each router. R1→R2→R3 is two hops.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$3.0 IP Connectivity$$::text, 25.0, 'bc6c99d12e92d1c4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e2299988-f1e0-5612-8494-36ea0f634304', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'topology', 3, 'apply', $$Refer to the IPv6 topology:

   [R1]---[R2]---[R3]
   2001:db8:1::/64  2001:db8:2::/64

R1 wants to send a packet to R3's link-local address. Which address will R1 use as the destination?$$::text, $$[{"id": "A", "text": "2001:db8:2::3", "is_correct": false}, {"id": "B", "text": "fe80::3 on the outgoing interface", "is_correct": true}, {"id": "C", "text": "ff02::1", "is_correct": false}, {"id": "D", "text": "::1", "is_correct": false}]$$::jsonb, $$Link-local addresses (fe80::/10) are used on the local link and must be scoped to the outgoing interface.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$1.0 Network Fundamentals$$::text, 15.0, 'bc99291bc1515708', true) ON CONFLICT (id) DO NOTHING;

